   t=script.string or '';t=t.replace("'../../fbr-submission.html", "'../../../fbr-submission.html").replace("href=\"../../", "href=\"../../../").replace("href=\"Ch", "href=\"../Ch").replace("reveal:'reveal/", "reveal:'../reveal/")
   # Different engines use literal reveal paths in the configuration.
   t=t.replace("fetch('reveal/", "fetch('../reveal/")
