  archivepath=f'lectures/iscarb/previous/Ch{n}-FBR-Student-Assignment.html';(ROOT/archivepath).parent.mkdir(exist_ok=True);(ROOT/archivepath).write_text(str(ar));archive.append(archivepath)
  s=BeautifulSoup(raw,'html.parser');s.html['data-assessment-edition']='mastery-v2'
