  script=script.replace('reliability claim','engineering claim').replace('reliability decision','engineering decision').replace('RELIABILITY DECISION','ENGINEERING DECISION').replace('reliability claim','technical claim').replace('calculation or reliability claim','calculation or technical claim').replace('metric/requirement','artifact/requirement').replace('Metric/requirement','Artifact/requirement').replace('checked the calculation','checked the technical reasoning')
  if n!=11:script=script.replace('MEASURE',step or 'TECHNICAL REASONING')
