  labels={'measure':step,'sourceUse':'ASSIGNED SOURCE APPLICATION','technical':'TRANSFER CHECK','labPrediction':'LAB PREDICTION','labCases':'EXECUTABLE TEST CASES','labEvidence':'LOCAL EXECUTION RECORD'}
  script=script.replace('x.toUpperCase()', '('+json.dumps(labels)+"[x]||x.toUpperCase())")
  extraB='''<section class="card"><h2>Workload and feedback cycle</h2><label class="field-label" for="activeMinutes">Total active minutes (optional)</label><p class="hint">Include required reading, preparation check and this assignment. Report actual time; it does not affect your grade.</p><input id="activeMinutes" type="number" min="0" max="1440"><details><summary>After instructor feedback · revised submission</summary><p>Leave these two fields blank for the first submission. After feedback, record one change and how you checked it, then update the final record and human review. Retaining a decision with a sound explanation is acceptable. Follow Blackboard for resubmission dates.</p><label for="feedbackNote">Feedback received</label><textarea id="feedbackNote"></textarea><label for="revisionNote">What changed or was retained, and how I rechecked it</label><textarea id="revisionNote"></textarea><p class="hint">The first prepared export is kept locally as a comparison snapshot. This page cannot verify an LMS submission.</p></details></section>'''
  script=script.replace('<section class="card"><h2>Export, then submit in the LMS</h2>',extraB+'<section class="card"><h2>Export, then submit in the LMS</h2>')
