  extension=(ROOT/'curriculum/learning-path/assignment-v2.js').read_text().replace('__V2_CONFIG__',json.dumps(cfg))
  if not script.endswith('boot();\n') and not script.rstrip().endswith('boot();'):raise ValueError('Unexpected engine ending')
