  s.select_one('#assignment-learning-path').insert_after(fragment(prep))
  for el in s.find_all(['p','div']):
   if not el.find_all(['section','table','div']) and 'Aim for' in el.get_text():
    el.string=('Keep the complete written response to about 180–260 focused words; use compact tables or notation. Include the source application and transfer answer in that budget. '+('The executable log replaces prose about hypothetical test execution. ' if n in [16,17] else 'No external experiment is required. ')+'State facts, assumptions and proposed evidence separately. Quote or cite the assigned source precisely; explain its role. Report actual study time at the end.')
  for chip in s.select('.chip'):
   if 'minutes' in chip.get_text():chip.string='45–65 min total' if n in [16,17] else '35–55 min total'
  s.select_one('header .sub').string='Read the named source pages, check the five objectives, apply the concepts, then reassess your decision when new evidence appears. The total-time estimate includes preparation; report your actual time.'
  # Clarify current task mappings without unverified national item codes inherited from A1/A2.
