  s.select_one('.rubric').find_parent('section').append(fragment(calibration))
  rows=s.select('.rubric tbody tr')
  for ri,row in enumerate(rows):
   cells=row.find_all(['td','th']);desc=BeautifulSoup(str(cells[1]),'html.parser').get_text(' ',strip=True);full=re.split(r'(?:0\.75:|0\.5:)',desc)[0];full=re.sub(r'^1:\s*','',full)
   if ri==0:full+=' The short transfer answer must correctly apply the second concept; FIT and transfer together earn this single point.'
   if (n!=10 and ri==1) or (n==10 and ri==0):full+=' Apply one named required source concept to the artifact and explain the connection.'
   if n in [16,17] and ri==1:full+=' Include your predicted outcomes, both local runs and a correct interpretation of any discrepancy; test logs replace a descriptive paragraph.'
   put(cells[1],'<b>1:</b> '+esc(full)+'<br><b>0.75:</b> Correct mechanism and conclusion, with one minor missing label, source detail or scope qualification.<br><b>0.5:</b> Some relevant reasoning, but a missing or incorrect mechanism, technical result, transfer explanation or evidence link materially weakens this criterion.<br><b>0:</b> Missing, materially wrong, or dependent on invented evidence. A generic “hold and test” statement without applying chapter concepts does not satisfy the criterion.')
  supplement=f'<section class="card"><p class="lab">ASSIGNED SOURCE APPLICATION · INCLUDED IN THE EXISTING RUBRIC</p><label class="field-label" for="sourceUse">Which assigned source concept supports your artifact?</label><p>Write the source slide number, explain the concept in your own words, and identify the specific part of your artifact it supports or challenges. Use the assigned pages above. A citation alone is insufficient.</p><textarea id="sourceUse" placeholder="Slide number — concept — connection to my artifact…"></textarea></section><section class="card"><p class="lab">TRANSFER CHECK · SCORED WITH FIT</p><label class="field-label" for="technical">Apply another chapter concept.</label><p>{esc(ST.STUDY[n]["technical"])}</p><textarea id="technical" placeholder="Two focused sentences or compact notation…"></textarea></section>'
  s.select_one('#lockBanner').insert_before(fragment(supplement))
